script.setup:
// Nonflowers by Lingdong Huang (MIT, https://github.com/LingDong-/nonflowers): procedurally generated
// paintings of flowers that don't exist. main.js is fetched from a pinned commit and run unchanged in a
// worker (it patches Array.prototype and Math.random, so it gets a realm of its own), with the page's DOM
// stubbed out. Its Layer helpers are swapped for equivalents that paint at 2x and skip empty pixels in the
// per-pixel filters, and every polygon it paints is recorded. The scene then reveals the finished
// painting through a mask redrawn from those polygons in the order they were painted, stroke by stroke.
const SRC = "https://cdn.jsdelivr.net/gh/LingDong-/nonflowers@03b653d220f16c6bed7ea9c7edc852f7e91846cb/main.js";
const res = await fetch(SRC);
if (!res.ok) throw new Error(`couldn't fetch Nonflowers (HTTP ${res.status}) from ${SRC}`);
const code = await res.text();
if (!code.includes("function herbal") || !code.includes("var Layer")) throw new Error(`Nonflowers source at ${SRC} doesn't look like main.js`);

const S = 2;     // device pixels per painting unit (the original paints its 600-unit sheet at 1x)
const SHEET = 600;

const workerSrc = `
let factory = null;
const doc = { createElement: () => new OffscreenCanvas(1, 1) };
const quiet = { log() {}, warn() {}, error() {} };
const S = ${S};
// main.js adds .x/.y/.z/[-1] accessors to Array.prototype each time it runs; the first run's stay.
const Obj = Object.create(Object, { defineProperty: { value: (o, k, d) => (Object.getOwnPropertyDescriptor(o, k) ? o : Object.defineProperty(o, k, d)) } });
onmessage = (e) => {
  const m = e.data;
  if (m.type === "init") {
    factory = new Function("window", "document", "console", "Math", "Object", "__rec",
      "var SEED, CTX, BGCANV, PAPER_COL0, PAPER_COL1, v3, vtxlist0, vtxlist1, vtxlist, context, p;\\n" + m.code +
      // the summary table is DOM-only; every polygon is also reported to __rec
      "\\nvizParams = function () {};\\nvar __polygon = polygon;\\npolygon = function (a) { __rec(a); return __polygon(a); };" +
      "\\nreturn { paper, woody, herbal, squircle, Layer, Noise, PAPER_COL0, PAPER_COL1 };");
    return;
  }
  try { const o = generate(m.seed, m.kind); o.id = m.id; postMessage(o, [o.painting, o.blank, o.bg, o.pts.buffer, o.start.buffer, o.fill.buffer]); }
  catch (err) { postMessage({ error: String(err && err.stack || err), seed: m.seed, id: m.id }); }
};

function generate(seed, kind) {
  const t0 = performance.now();
  const M = Object.create(Math);
  const ops = []; // [pts, xof, yof]
  let rec = null;
  const lib = factory({ btoa: (s) => btoa(s), location: { href: "" } }, doc, quiet, M, Obj, (a) => rec && rec(a));
  const L = lib.Layer;
  // Same as the original Layer helpers, but canvases hold S device pixels per unit and the per-pixel
  // filters skip fully transparent pixels (their result is transparent either way).
  L.empty = (w = 600, h = w) => {
    const c = new OffscreenCanvas(w * S, h * S);
    const g = c.getContext("2d", { willReadFrequently: true });
    g.setTransform(S, 0, 0, S, 0, 0);
    return g;
  };
  let blitAt = null;
  L.blit = (g0, g1, a = {}) => {
    const ble = a.ble ?? "normal", xof = a.xof ?? 0, yof = a.yof ?? 0;
    if (!blitAt) blitAt = [xof, yof];
    g0.globalCompositeOperation = ble; // "normal" isn't a valid value, so (as in the original) it stays "multiply"
    g0.drawImage(g1.canvas, xof, yof, g1.canvas.width / S, g1.canvas.height / S);
  };
  L.filter = (g, f) => {
    const W = g.canvas.width, H = g.canvas.height;
    const im = g.getImageData(0, 0, W, H), px = im.data;
    for (let y = 0, i = 0; y < H; y++) for (let x = 0; x < W; x++, i += 4) {
      if (px[i + 3] === 0) continue;
      const o = f(x / S, y / S, px[i], px[i + 1], px[i + 2], px[i + 3]);
      px[i] = o[0]; px[i + 1] = o[1]; px[i + 2] = o[2]; px[i + 3] = o[3];
    }
    g.putImageData(im, 0, 0);
  };
  L.bound = (g) => {
    const W = g.canvas.width, H = g.canvas.height, px = g.getImageData(0, 0, W, H).data;
    let xmin = W, xmax = 0, ymin = H, ymax = 0;
    for (let y = 0, i = 3; y < H; y++) for (let x = 0; x < W; x++, i += 4) if (px[i] > 0) {
      if (x < xmin) xmin = x; if (x > xmax) xmax = x; if (y < ymin) ymin = y; if (y > ymax) ymax = y;
    }
    return { xmin: xmin / S, xmax: xmax / S, ymin: ymin / S, ymax: ymax / S };
  };
  L.border = (g, f) => {
    const W = g.canvas.width, H = g.canvas.height, im = g.getImageData(0, 0, W, H), px = im.data;
    for (let y = 0, i = 0; y < H; y++) for (let x = 0; x < W; x++, i += 4) {
      const nx = (x / W - 0.5) * 2, ny = (y / H - 0.5) * 2;
      if (Math.hypot(nx, ny) > f(Math.atan2(ny, nx))) { px[i] = px[i + 1] = px[i + 2] = px[i + 3] = 0; }
    }
    g.putImageData(im, 0, 0);
  };

  // What the page does for ?seed=<seed>: seed, paint the page background (makeBG), then generate().
  M.seed(seed);
  const bg = lib.paper({ col: lib.PAPER_COL0, tex: 10, spr: 0 });
  const CTX = L.empty();
  CTX.fillStyle = "white";
  CTX.fillRect(0, 0, 600, 600);
  const ppr = lib.paper({ col: lib.PAPER_COL1 });
  for (let i = 0; i < 600; i += 512) for (let j = 0; j < 600; j += 512) CTX.drawImage(ppr, i, j);
  const blank = L.empty();
  blank.drawImage(CTX.canvas, 0, 0, 600, 600);
  const woody = M.random() <= 0.5;
  const isWoody = kind === 1 ? true : kind === 2 ? false : woody;
  rec = (a) => ops.push([a.pts, a.xof || 0, a.yof || 0, a.fil !== false]);
  const t1 = performance.now();
  if (isWoody) lib.woody({ ctx: CTX, xof: 300, yof: 550 });
  else lib.herbal({ ctx: CTX, xof: 300, yof: 600 });
  rec = null;
  const t2 = performance.now();
  L.border(CTX, lib.squircle(0.98, 3));
  L.border(blank, lib.squircle(0.98, 3));

  // flatten the recorded polygons into sheet units
  const [bx, by] = blitAt || [0, 0];
  let n = 0;
  for (const o of ops) n += o[0].length;
  const pts = new Float32Array(n * 2), start = new Uint32Array(ops.length + 1), fill = new Uint8Array(ops.length);
  let k = 0;
  ops.forEach((o, i) => {
    start[i] = k;
    fill[i] = o[3] ? 1 : 0;
    for (const p of o[0]) { pts[2 * k] = p[0] + o[1] + bx; pts[2 * k + 1] = p[1] + o[2] + by; k++; }
  });
  start[ops.length] = k;
  const out = {
    seed, woody: isWoody, pts, start, fill,
    painting: CTX.canvas.transferToImageBitmap(), blank: blank.canvas.transferToImageBitmap(),
    bg: bg.transferToImageBitmap(), ms: [t1 - t0, t2 - t1, performance.now() - t2].map(Math.round),
  };
  return out;
}
`;
const worker = new Worker(URL.createObjectURL(new Blob([workerSrc], { type: "text/javascript" })));
worker.postMessage({ type: "init", code });

const gl = ctx.gl;
function makeTex(wrap = gl.CLAMP_TO_EDGE) {
  const t = gl.createTexture();
  gl.bindTexture(gl.TEXTURE_2D, t);
  for (const [k, v] of [[gl.TEXTURE_MIN_FILTER, gl.LINEAR_MIPMAP_LINEAR], [gl.TEXTURE_MAG_FILTER, gl.LINEAR], [gl.TEXTURE_WRAP_S, wrap], [gl.TEXTURE_WRAP_T, wrap]]) gl.texParameteri(gl.TEXTURE_2D, k, v);
  gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, 1, 1, 0, gl.RGBA, gl.UNSIGNED_BYTE, new Uint8Array([0, 0, 0, 0]));
  return t;
}
function upload(t, img, mip = true) {
  gl.bindTexture(gl.TEXTURE_2D, t);
  gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, false);
  gl.pixelStorei(gl.UNPACK_PREMULTIPLY_ALPHA_WEBGL, true);
  gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, img);
  gl.pixelStorei(gl.UNPACK_PREMULTIPLY_ALPHA_WEBGL, false);
  if (mip) gl.generateMipmap(gl.TEXTURE_2D);
}

// The reveal mask: the recorded polygons redrawn in white, in painting order, at 1 px per unit.
const MS = 1;
const maskCv = new OffscreenCanvas(SHEET * MS, SHEET * MS);
const mg = maskCv.getContext("2d");
const maskTex = makeTex();
gl.bindTexture(gl.TEXTURE_2D, maskTex);
gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);

function clearMask() {
  mg.setTransform(1, 0, 0, 1, 0, 0);
  mg.fillStyle = "#000";
  mg.fillRect(0, 0, maskCv.width, maskCv.height);
}
function drawOp(f, i) {
  const a = f.start[i], b = f.start[i + 1], p = f.pts;
  if (b - a < 2) return;
  mg.beginPath();
  mg.moveTo(p[2 * a], p[2 * a + 1]);
  for (let k = a + 1; k < b; k++) mg.lineTo(p[2 * k], p[2 * k + 1]);
  if (f.fill[i]) mg.fill();
  mg.stroke();
}
function beginMask() {
  mg.setTransform(MS, 0, 0, MS, 0, 0);
  mg.fillStyle = "#fff";
  mg.strokeStyle = "#fff";
  mg.lineWidth = 1.5;
  mg.lineJoin = "round";
}

const fs = `#version 300 es
precision highp float;
in vec2 v_uv; out vec4 outColor;
uniform sampler2D u_bg, u_blank, u_paint, u_mask, u_blankNext;
uniform vec2 u_resolution, u_brushPos;
uniform float u_sheetPx, u_ink, u_next, u_brushOn;
vec4 sheetAt(vec2 sp) {
  // sample unconditionally (an early return would break the mip selection along the sheet's edge)
  vec2 uv = sp / 600.0;
  float inside = step(0.0, uv.x) * step(0.0, uv.y) * step(uv.x, 1.0) * step(uv.y, 1.0);
  vec4 blank = mix(texture(u_blank, uv), texture(u_blankNext, uv), u_next);
  vec4 paint = texture(u_paint, uv);
  float m = texture(u_mask, uv).r * u_ink;
  return mix(blank, paint, m) * inside;
}
void main() {
  vec2 px = vec2(v_uv.x, 1.0 - v_uv.y) * u_resolution; // y down
  vec2 origin = 0.5 * (u_resolution - vec2(u_sheetPx));
  float k = u_sheetPx / 600.0;
  vec2 sp = (px - origin) / k;
  // the page: Nonflowers' own background paper tile, at the sheet's scale
  vec3 col = texture(u_bg, px / (512.0 * k)).rgb;
  // soft shadow under the sheet: Nonflowers trims it with squircle(0.98, 3), i.e. |x|^3 + |y|^3 = 0.98^3
  vec2 sn = abs((sp - vec2(6.0, 10.0)) / 300.0 - 1.0);
  float sd = pow(pow(sn.x, 3.0) + pow(sn.y, 3.0), 1.0 / 3.0) - 0.98;
  col *= 1.0 - 0.3 * exp(-max(sd, 0.0) * 300.0 / 16.0) * smoothstep(-0.2, 0.0, sd);
  col *= 1.0 - 0.18 * pow(length(v_uv - 0.5) * 1.3, 2.5);
  vec4 s = sheetAt(sp);
  col = col * (1.0 - s.a) + s.rgb; // premultiplied
  // a faint wet glint under the brush while it paints
  float r = length(px - u_brushPos) / k;
  col *= 1.0 - u_brushOn * 0.06 * exp(-r * r / 300.0);
  outColor = vec4(col, 1.0);
}`;

Object.assign(ctx.state, {
  worker, makeTex, upload, clearMask, drawOp, beginMask, maskCv, maskTex,
  bgTex: makeTex(gl.REPEAT), blankTex: makeTex(), paintTex: makeTex(), nextBlankTex: makeTex(),
  prog: ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, fs),
  cur: null, next: null, pending: false, phase: "wait", phaseT: 0, shown: 0, bgSet: false, lastKind: ctx.uniforms.u_kind,
  error: null, revealed: null,
});
// The first painting is generated before the scene starts, so it paints from the very first frame.
ctx.state.next = await new Promise((resolve, reject) => {
  worker.onmessage = (e) => (e.data.error ? reject(new Error("Nonflowers generator failed: " + e.data.error)) : resolve(e.data));
  worker.postMessage({ type: "gen", seed: String(ctx.uniforms.u_seed | 0), kind: ctx.uniforms.u_kind | 0 });
});
ctx.state.phase = "wait";
worker.onmessage = (e) => {
  const s = ctx.state;
  if (e.data.id !== s.reqId) return; // superseded by a newer request (seed or plant changed)
  s.pending = false;
  if (e.data.error) { s.error = e.data.error; return; }
  s.next = e.data;
};
ctx.state.reqId = 0;
ctx.state.request = (seed) => {
  const s = ctx.state;
  s.pending = true;
  s.next = null;
  worker.postMessage({ type: "gen", id: ++s.reqId, seed: String(seed), kind: ctx.uniforms.u_kind | 0 });
};
clearMask();

script.render:
const s = ctx.state, gl = ctx.gl, u = ctx.uniforms;
const dt = Math.min(ctx.dt, 0.1);
const [W, H] = ctx.resolution;
if (s.error) throw new Error("Nonflowers generator failed: " + s.error);

// layout: the square sheet, as large as fits with a margin (any aspect, never stretched)
const sheetPx = Math.min(W, H) * (W > H ? 0.9 : 0.92);
const k = sheetPx / 600, ox = (W - sheetPx) / 2, oy = (H - sheetPx) / 2;

function adopt() {
  const f = s.next;
  s.next = null;
  if (!s.bgSet) { s.upload(s.bgTex, f.bg); s.bgSet = true; }
  s.upload(s.blankTex, f.blank);
  s.upload(s.paintTex, f.painting);
  s.cur = f;
  s.revealed = new Uint8Array(f.fill.length);
  s.cursor = 0; s.done = 0; s.acc = 0;
  s.clearMask();
  s.maskDirty = true;
  s.phase = "paint"; s.phaseT = 0;
  s.request(1 + Math.floor(Math.random() * 999999));
}

// controls
const seedNow = u.u_seed | 0;
if (s.seedUniform === undefined) s.seedUniform = seedNow;
if (seedNow !== s.seedUniform || (u.u_kind | 0) !== s.lastKind) {
  s.seedUniform = seedNow; s.lastKind = u.u_kind | 0;
  s.request(seedNow); s.force = true;
}
if (u.u_new && s.phase !== "out") s.force = true;

s.phaseT += dt;
if (s.phase === "wait" && s.next) adopt();
else if (s.phase === "paint" || s.phase === "hold") {
  if (s.force && s.next) { s.phase = "out"; s.phaseT = 0; s.force = false; }
}

let inkFade = 1, nextMix = 0;
const f = s.cur;
if (f && s.phase === "paint") {
  const N = f.fill.length;
  s.beginMask();
  // brush: pressing on the sheet paints the strokes under it first
  const mx = (ctx.mouse[0] * W - ox) / k, my = (ctx.mouse[1] * H - oy) / k;
  s.brushOn = ctx.mouseDown && mx > 0 && my > 0 && mx < 600 && my < 600;
  if (s.brushOn) {
    const R2 = (u.u_brush * u.u_brush), p = f.pts, st = f.start;
    let n = 0;
    for (let i = 0; i < N && n < 600; i++) {
      if (s.revealed[i]) continue;
      const a = st[i];
      const dx = p[2 * a] - mx, dy = p[2 * a + 1] - my;
      if (dx * dx + dy * dy < R2) { s.drawOp(f, i); s.revealed[i] = 1; s.done++; n++; }
    }
    if (n) s.maskDirty = true;
    s.brush = [ctx.mouse[0] * W, ctx.mouse[1] * H];
  }
  // the painter: strokes in the order Nonflowers painted them
  s.acc += (N / 9) * u.u_speed * dt;
  while (s.acc >= 1 && s.cursor < N) {
    if (!s.revealed[s.cursor]) { s.drawOp(f, s.cursor); s.revealed[s.cursor] = 1; s.done++; s.acc -= 1; s.maskDirty = true; }
    s.cursor++;
  }
  if (!s.brushOn && s.cursor > 0) {
    const a = f.start[Math.min(s.cursor, N) - 1];
    s.brush = [ox + f.pts[2 * a] * k, oy + f.pts[2 * a + 1] * k];
  }
  if (s.cursor >= N) { s.phase = "hold"; s.phaseT = 0; }
} else if (s.phase === "hold") {
  s.brushOn = false;
  if (s.phaseT > u.u_hold && s.next) { s.phase = "out"; s.phaseT = 0; }
}
if (s.phase === "out") {
  if (s.phaseT < 0.01 && s.next) s.upload(s.nextBlankTex, s.next.blank);
  const t = Math.min(1, s.phaseT / 1.6);
  inkFade = 1 - t * t * (3 - 2 * t);
  nextMix = 1 - inkFade;
  if (t >= 1 && s.next) adopt(), (inkFade = 1), (nextMix = 0);
}
if (s.maskDirty) {
  gl.bindTexture(gl.TEXTURE_2D, s.maskTex);
  gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, false);
  gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, s.maskCv);
  s.maskDirty = false;
}
if (f) {
  ctx.publish("seed", f.seed);
  ctx.publish("plant", f.woody ? "woody" : "herbaceous");
  ctx.publish("painted %", Math.round((100 * s.done) / Math.max(1, f.fill.length)));
  ctx.publish("strokes", f.fill.length);
  ctx.publish("gen ms", f.ms.join(" / "));
}

gl.useProgram(s.prog);
ctx.utils.setUniforms(s.prog, {
  u_resolution: [W, H], u_sheetPx: sheetPx, u_ink: inkFade, u_next: nextMix,
  u_brushPos: s.brush || [0, 0], u_brushOn: s.phase === "paint" ? 1 : 0,
});
ctx.utils.bindTexture(s.prog, "u_bg", s.bgTex, 0);
ctx.utils.bindTexture(s.prog, "u_blank", s.blankTex, 1);
ctx.utils.bindTexture(s.prog, "u_paint", s.paintTex, 2);
ctx.utils.bindTexture(s.prog, "u_mask", s.maskTex, 3);
ctx.utils.bindTexture(s.prog, "u_blankNext", s.nextBlankTex, 4);
ctx.utils.drawFullscreen(s.prog);
